-- Mehrsprachigkeit im Texte-CMS: eine Spalte je Sprache. Leer heißt: Die App nimmt die mitgelieferte
-- Übersetzung aus src/i18n/<sprache>.json. Moderatorinnen ändern die Spalten im Editor (Dein Konto › Texte)
-- oder im Table Editor. Dazu alle Texte der App, nicht nur Buttons, Kater und Rechtstexte.
-- Voraussetzung: 0900 (app_texts) und 1300 (Texte ändern).

alter table public.app_texts
  add column if not exists en text,
  add column if not exists fr text,
  add column if not exists uk text,
  add column if not exists ar text,
  add column if not exists he text;

grant update (text, en, fr, uk, ar, he) on public.app_texts to authenticated;

-- Zeitstempel auch bei Änderungen an Übersetzungen
drop trigger if exists app_texts_touch on public.app_texts;
create trigger app_texts_touch
  before update of text, en, fr, uk, ar, he on public.app_texts
  for each row execute function public.touch_app_texts();

-- 882 Texte aus dem Code (scripts/app-texts.mjs)
on conflict (original) do update set ort = excluded.ort;
